package com.fitnutri.backend.records.food;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.support.UxV3Fixtures;
import com.fitnutri.backend.common.BusinessException;
import java.math.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class DishCalculationTest {
 private final PortionNormalizer portions=new PortionNormalizer();private final DishCalculationService calculator=new DishCalculationService(new FoodCalculationService());
 private PortionNormalizer.Portion third(){return portions.normalisePortion("FULL_RECIPE",Map.of("kind","FRACTION","numerator",1,"denominator",3));}
 @Test void independent1700ExampleAndPercentAreDifferent(){var refs=UxV3Fixtures.syntheticFoodRefs();var a=calculator.calculateScaledReference(refs.get(0),new BigDecimal("300"),third(),false);var b=calculator.calculateScaledReference(refs.get(1),new BigDecimal("150"),third(),false);assertEquals(new BigDecimal("100.000000000000"),a.consumedGrams());assertEquals(new BigDecimal("50.000000000000"),b.consumedGrams());assertEquals(new BigDecimal("1200.000"),DishCalculationService.sumRoundedLeaves(List.of(a.nutrients(),b.nutrients())).energyKj());var c=new FoodCalculationService().calculate(refs.get(2),new BigDecimal("100"));assertEquals(new BigDecimal("1700.000"),DishCalculationService.sumRoundedLeaves(List.of(a.nutrients(),b.nutrients(),c)).energyKj());var percent=portions.normalisePortion("FULL_RECIPE",Map.of("kind","PERCENT","percent",new BigDecimal("33.3")));assertEquals(new BigDecimal("1198.800"),DishCalculationService.sumRoundedLeaves(List.of(calculator.calculateScaledReference(refs.get(0),new BigDecimal("300"),percent,false).nutrients(),calculator.calculateScaledReference(refs.get(1),new BigDecimal("150"),percent,false).nutrients())).energyKj());}
 @Test void finalLeafRoundingNeverUsesRoundedFullRecipeOrConsumedGrams(){var ref=UxV3Fixtures.syntheticFoodRefs().getFirst();ref.setEnergyKj100g(new BigDecimal("50"));var result=calculator.calculateScaledReference(ref,new BigDecimal("0.004"),third(),false);assertEquals(new BigDecimal("0.001"),result.nutrients().energyKj());assertEquals(new BigDecimal("0.001333333333"),result.consumedGrams());ref.setEnergyKj100g(new BigDecimal("0.150"));assertEquals(new BigDecimal("0.001"),calculator.calculateScaledReference(ref,BigDecimal.ONE,third(),false).nutrients().energyKj());var half=portions.normalisePortion("FULL_RECIPE",Map.of("kind","FRACTION","numerator",1,"denominator",2));ref.setEnergyKj100g(new BigDecimal("50"));assertEquals(new BigDecimal("0.000"),calculator.calculateScaledReference(ref,new BigDecimal("0.001"),half,false).nutrients().energyKj());ref.setEnergyKj100g(new BigDecimal("0.001"));assertEquals(new BigDecimal("0.000"),calculator.calculateScaledReference(ref,new BigDecimal("0.001"),third(),false).nutrients().energyKj());}
 @Test void smallestAllowedInputRetainsPositiveConsumedGramsAndNormalValidation(){var ref=UxV3Fixtures.syntheticFoodRefs().getFirst();var tiny=portions.normalisePortion("FULL_RECIPE",Map.of("kind","PERCENT","percent",new BigDecimal("0.001")));assertEquals(new BigDecimal("0.000000010000"),calculator.calculateScaledReference(ref,new BigDecimal("0.001"),tiny,false).consumedGrams());for(String grams:List.of("0","-1","10000.001","0.0001"))assertThrows(BusinessException.class,()->calculator.calculateScaledReference(ref,new BigDecimal(grams),third(),false));ref.setActive(false);assertThrows(BusinessException.class,()->calculator.calculateScaledReference(ref,new BigDecimal("100"),third(),false));assertNotNull(calculator.calculateScaledReference(ref,new BigDecimal("100"),third(),true));ref.setProteinG100g(null);assertThrows(BusinessException.class,()->calculator.calculateScaledReference(ref,new BigDecimal("100"),third(),true));}
 @Test void scaledResultDoesNotOverflowFromPrematureFullRecipeAndRejectsFinalOverflow(){var ref=UxV3Fixtures.syntheticFoodRefs().getFirst();ref.setEnergyKj100g(new BigDecimal("999999999"));var tiny=portions.normalisePortion("FULL_RECIPE",Map.of("kind","FRACTION","numerator",1,"denominator",1000000));assertNotNull(calculator.calculateScaledReference(ref,new BigDecimal("10000"),tiny,false));assertThrows(BusinessException.class,()->calculator.calculateScaledReference(ref,new BigDecimal("10000"),third(),false));}
}
